import {Component,type ReactNode} from "react";
class Limite extends Component<{children:ReactNode},{erro:boolean}>{state={erro:false};static getDerivedStateFromError(){return {erro:true}};render(){return this.state.erro?<p role="alert">Não foi possível abrir esta seção.</p>:this.props.children}}
export default function App(){return <Limite><p>Conteúdo estável</p></Limite>}

