import {lazy,Suspense} from "react";
const Ajuda=lazy(()=>Promise.resolve({default:()=> <aside>Ajuda carregada</aside>}));
export default function App(){return <main><h1>Painel</h1><Suspense fallback={<p>Carregando ajuda</p>}><Ajuda/></Suspense></main>}

